contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 attemptDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (attemptDeposit)); require(attemptDeposit <= 1000000000000000000000000000000);
        c.addToBalance{value: attemptDeposit}(); if (__ESBMC_reverted()) return;
        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint256 priorRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 priorContractEther = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && priorRecorded == 0 && c.getBalance(address(this)) == priorRecorded && address(c).balance == priorContractEther);
    }

    receive() external payable {}
}

