pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 attemptDeposit) internal {
        attemptDeposit = bound(attemptDeposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        try c.addToBalance{value: attemptDeposit}() {} catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint256 priorRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { priorRecorded = __r; } catch { return; }
        uint256 priorContractEther = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && priorRecorded == 0 && c.getBalance(address(this)) == priorRecorded && address(c).balance == priorContractEther);
    }

    function testFuzz_run(uint256 attemptDeposit) public {
        _run(attemptDeposit);
    }

    receive() external payable {}
}
